             { id: "c", label: "C", correct: true },
             { id: "html", label: "HTML", correct: false },
             { id: "go", label: "Go", correct: true },
           ],
         },
         {
           id: "web-languages",
           prompt: "Which languages are core technologies for building web pages?",
           choices: [
             { id: "javascript", label: "JavaScript", correct: true },
             { id: "css", label: "CSS", correct: true },
             { id: "html", label: "HTML", correct: true },
             { id: "sql", label: "SQL", correct: false },
           ],
         },
         {
           id: "memory-safety",
           prompt: "Which languages are known for strong memory-safety features?",
           choices: [
             { id: "rust", label: "Rust", correct: true },
             { id: "swift", label: "Swift", correct: true },
             { id: "python", label: "Python", correct: true },
             { id: "assembly", label: "Assembly", correct: false },
           ],
         },
       ];

       function Choice({ questionId, choice }) {
         const inputId = `${questionId}-${choice.id}`;

         return `
           <label class="choice" for="${inputId}">
             <input
               id="${inputId}"
               type="checkbox"
               name="${questionId}"
               value="${choice.id}"
               data-correct="${choice.correct}"
             >
             <span class="choice-text">${choice.label}</span>
           </label>
         `;
       }

       function Question({ question, index }) {
         const helpId = `${question.id}-help`;
         const describedBy = question.help ? ` aria-describedby="${helpId}"` : "";
         const helpText = question.help
           ? `<p class="help-text" id="${helpId}">${question.help}</p>`
           : "";
         const choices = question.choices
           .map((choice) => Choice({ questionId: question.id, choice }))
           .join("");

         return `
           <div class="form-field">
             <fieldset${describedBy}>
               <legend>${index + 1}. ${question.prompt}</legend>
               ${helpText}
               <div class="choices">
                 ${choices}
               </div>
             </fieldset>
           </div>
         `;
       }

       function QuizApp({ questions }) {
         const questionMarkup = questions
           .map((question, index) => Question({ question, index }))
           .join("");

         return `
           <form id="quiz-form" novalidate>
             ${questionMarkup}
             <div class="actions">
               <button type="submit">Submit answers</button>
               <p class="result" id="quiz-result" aria-live="polite"></p>
             </div>
           </form>
         `;
       }

       function scoreQuestion(form, question) {
         return question.choices.every((choice) => {
           const input = form.elements[`${question.id}-${choice.id}`];
           return input.checked === choice.correct;
         });
       }

       function handleSubmit(event) {
         event.preventDefault();

         const form = event.currentTarget;
         const correctCount = questions.filter((question) =>
           scoreQuestion(form, question)
         ).length;
         const result = document.querySelector("#quiz-result");

         result.textContent = `You scored ${correctCount} out of ${questions.length}.`;
       }

       function renderQuiz() {
         const root = document.querySelector("#quiz-root");
         root.innerHTML = QuizApp({ questions });
         root.querySelector("#quiz-form").addEventListener("submit", handleSubmit);
       }

